MultiLanguageSpellData['it'][290108] = {name = "Rinnovamento", additional_info = "{1.8% della base mana} {Portata di 40 m}\nIstantaneo\n[q]Riempie il bersaglio di fede nella Luce, curandolo istantaneamente di 2 e di 9 aggiuntivi in 15 s."}
