MultiLanguageSpellData['it'][290110] = {name = "Parola Sacra: Castigo", additional_info = "{2% della base mana} {Portata di 30 m}\n{Istantaneo} {1 min di recupero}\n[q]Castiga il bersaglio, infliggendo (112.5% of Spell power) danni da sacro e inabilitandolo per 4 s.\n\nSacro\n[q]Cooldown reduced by 4 sec when you cast Smite."}
