MultiLanguageSpellData['it'][290112] = {name = "Cura Combinata", additional_info = "{2.9% della base mana} {Portata di 40 m}\n1.5 s di lancio\n[q]Cura te, il tuo bersaglio e un altro bersaglio alleato entro 20 m di 5.\n\nRiduce il tempo di recupero restante di Parola Sacra: Serenità e Parola Sacra: Santificazione di 0 s."}
