MultiLanguageSpellData['it'][299333] = {name = "Sangue Vitale", additional_info = "Sangue Vitale Livello 80\n[q0][Azerite Essence][q]Ogni 1-25 s, una Scheggia di Sangue Vitale erutta dal terreno circostante per 18 s.\n\nScheggia di Sangue Vitale\n Aumenta l'attributo primario di se stessi e di tutti gli alleati con Risonanza della Vena del Mondo entro 12 m dalla Scheggia di Sangue Vitale di 13 . È possibile beneficiare di massimo 4 Schegge di Sangue Vitale alla volta."}
MultiLanguageSpellData['it'][299334] = {name = "Risonanza della Vena del Mondo", additional_info = "Risonanza della Vena del Mondo Livello 80\n[q0][Azerite Essence]{Istantaneo} {1 min di recupero}\n[q]Concentra l'energia nel Cuore di Azeroth, facendo eruttare istantaneamente dal terreno 3 Scheggia di Sangue Vitale per 18 s e aumentando l'attributo primario fornito dalle Schegge di Sangue Vitale del 300% per 18 s.\n\nScheggia di Sangue Vitale\n Aumenta l'attributo primario di se stessi e di tutti gli alleati con Risonanza della Vena del Mondo entro [ 8 * (1.5)] m da una Scheggia di Sangue Vitale di 13 . È possibile beneficiare di massimo 4 Schegge di Sangue Vitale alla volta."}
MultiLanguageSpellData['it'][299335] = {name = "Energia Concentrata", additional_info = "Energia Concentrata Livello 80\n[q0][Azerite Essence][q]Gli incantesimi e le abilità d'attacco aumentano l'indice di celerità di [ 5 * (1.5)] per 4 s. Si accumula fino a 10 volte. La celerità accumulata si dissolve se si cambia bersaglio."}
MultiLanguageSpellData['it'][299336] = {name = "Raggio Focalizzato d'Azerite", additional_info = "Raggio Focalizzato d'Azerite Livello 80\n[q0][Azerite Essence]{1.333 s di lancio} {1.5 min di recupero}\n[q]Concentra l'energia d'Azerite in eccesso nel Cuore di Azeroth, quindi la espelle verso l'esterno, infliggendo ( 891 * 10) danni da fuoco a tutti i nemici frontali in 3 s."}
MultiLanguageSpellData['it'][299337] = {name = "Energia Concentrata", additional_info = "Energia Concentrata Livello 80\n[q0][Azerite Essence][q]Gli incantesimi e le abilità d'attacco aumentano l'indice di celerità di [ 5 * (1.5)] per 4 s. Si accumula fino a 10 volte. La celerità accumulata si dissolve se si cambia bersaglio.\n\n Se non si hanno accumuli di Energia Concentrata, fornisce 3 accumuli al primo incantesimo o abilità d'attacco."}
MultiLanguageSpellData['it'][299338] = {name = "Raggio Focalizzato d'Azerite", additional_info = "Raggio Focalizzato d'Azerite Livello 80\n[q0][Azerite Essence]{1.333 s di lancio} {1.5 min di recupero}\n[q]Concentra l'energia d'Azerite in eccesso nel Cuore di Azeroth, quindi la espelle verso l'esterno, infliggendo ( 891 * 10) danni da fuoco a tutti i nemici frontali in 3 s. Può essere lanciato in movimento."}
MultiLanguageSpellData['it'][299342] = {name = "Pesce Palla", additional_info = "Portata di 6 m\n2 s di lancio\n[q]Infligge danni da natura ai nemici vicini."}
MultiLanguageSpellData['it'][299343] = {name = "Protocollo di Purificazione", additional_info = "Protocollo di Purificazione Livello 80\n[q0][Azerite Essence]Circa 2 apparenze ogni minuto\n[q]La M.A.D.R.E. ha aggiunto un Protocollo di Purificazione al tuo Cuore di Azeroth, permettendo ai tuoi incantesimi e abilità d'attacco di scatenare una detonazione d'Azerite contro il bersaglio, infliggendo [ 563 * (1 + Versatility)] danni da fuoco a qualsiasi nemico entro 8 m e curandoti di [ 255 * (1 + Versatility)] ogni 2 s per 8 s.\n\n Il Protocollo di Purificazione infligge il 50 % di danni aggiuntivi contro le Aberrazioni."}
MultiLanguageSpellData['it'][299344] = {name = "Bolla di Salvataggio", additional_info = "{Istantaneo} {10 s di recupero}\n[q]Diventa invulnerabile per 3 s, dissolvendo tutti gli effetti di veleno, malattia e magia, e curando del 35% della salute massima."}
MultiLanguageSpellData['it'][299345] = {name = "Detonazione Purificante", additional_info = "Detonazione Purificante Livello 80\n[q0][Azerite Essence]Portata di 40 m\n{Istantaneo} {1 min di recupero}\n[q]Richiama un raggio purificante sull'area bersaglio, infliggendo [ 395 * (1 + Versatility) * 7 ] danni da fuoco in 6 s. Ha una bassa probabilità di annientare istantaneamente ogni presenza giudicata non degna dalla M.A.D.R.E.\n\n Le Aberrazioni colpite dal raggio vengono stordite per 3 s."}
MultiLanguageSpellData['it'][299346] = {name = "Protocollo di Purificazione", additional_info = "Protocollo di Purificazione Livello 80\n[q0][Azerite Essence]Circa 2 apparenze ogni minuto\n[q]La M.A.D.R.E. ha aggiunto un Protocollo di Purificazione al tuo Cuore di Azeroth, permettendo ai tuoi incantesimi e abilità d'attacco di scatenare una detonazione d'Azerite contro il bersaglio, infliggendo [ 563 * (1.25) * (1 + Versatility)] danni da fuoco a qualsiasi nemico entro 8 m e curandoti di [ 255 * (1 + Versatility)] ogni 2 s per 8 s.\n\n Il Protocollo di Purificazione infligge il 50 % di danni aggiuntivi contro le Aberrazioni."}
MultiLanguageSpellData['it'][299347] = {name = "Detonazione Purificante", additional_info = "Detonazione Purificante Livello 80\n[q0][Azerite Essence]Portata di 40 m\n{Istantaneo} {1 min di recupero}\n[q]Richiama un raggio purificante sull'area bersaglio, infliggendo [ 395 * (1 + Versatility) * 7 ] danni da fuoco in 6 s. Ha una bassa probabilità di annientare istantaneamente ogni presenza giudicata non degna dalla M.A.D.R.E.\n\n Quando un nemico muore nell'area d'effetto del raggio, aumenta i tuoi danni del 10% per 8 s.\n\n Le Aberrazioni colpite dal raggio vengono stordite per 3 s."}
MultiLanguageSpellData['it'][299348] = {name = "Fiamma Antica", additional_info = "Fiamma Antica Livello 80\n[q0][Azerite Essence]Circa 1.25 apparenze ogni minuto\n[q]Gli incantesimi e le abilità hanno una probabilità di cauterizzare il bersaglio, infliggendo [ 351 * 5 * (1.25)] danni da fuoco a un nemico in 10 s o rigenerando [ 351 * 5 * (1.25)] salute a un alleato in 10 s."}
MultiLanguageSpellData['it'][299349] = {name = "Fiamma Concentrata", additional_info = "Fiamma Concentrata Livello 80\n[q0][Azerite Essence]Portata di 40 m\n{Istantaneo} {30 s di recupero}\n1 Carico\n[q]Colpisce il bersaglio con una sfera di fiamme concentrate, infliggendo [ 824 * (1 + Versatility)] danni da fuoco a un nemico o curando un alleato di [ 824 * (1 + Versatility)] salute, quindi brucia un bersaglio infliggendo il 75% dei danni inflitti o delle cure fornite in 6 s.\n\n Ogni lancio di Fiamma Concentrata infligge danni o fornisce cure aumentati del 100 %. Questo bonus viene azzerato a ogni terzo lancio."}
MultiLanguageSpellData['it'][299350] = {name = "Fiamma Antica", additional_info = "Fiamma Antica Livello 80\n[q0][Azerite Essence]Circa 1.25 apparenze ogni minuto\n[q]Gli incantesimi e le abilità hanno una probabilità di cauterizzare il bersaglio, infliggendo [ 351 * 5 * (1.25)] danni da fuoco a un nemico in 10 s o rigenerando [ 351 * 5 * (1.25)] salute a un alleato in 10 s. Si accumula fino a 3 volte."}
