MultiLanguageSpellData['it'][300266] = {name = "[q3]Spruzzabot Arancione", additional_info = "1.5 s di lancio\nReagenti:\nPezzi di Ricambio (50)\n[q3]Spruzzabot Arancione\n(20)\nSi vincola alla raccolta\n[q2]Usa: Crea uno Spruzzabot caricato con vernice arancione. (5 Min Recupero)\n[q]\"Uno Spruzzabot automatico caricato con vernice arancione.\""}
