MultiLanguageSpellData['it'][300269] = {name = "[q2]Meccartiglio Funzionale", additional_info = "1.5 s di lancio\nReagenti:\nCassa di Pezzi di Ricambio (3), Cella d'Energia (3), Bobina d'Innesco a Catena (5)\n[q2]Meccartiglio Funzionale\nSi vincola alla raccolta\n[q2]Usa: Ti insegna a evocare questa mascotte.\n[q2]Clicca col pulsante destro per evocare e congedare questa mascotte.\nRichiede dal livello 1 al 80 ( 80)"}
MultiLanguageSpellData['it'][300270] = {name = "[q3]Microbot XD", additional_info = "1.5 s di lancio\nReagenti:\nCassa di Pezzi di Ricambio (5), Cella d'Energia (4), Bobina d'Innesco a Catena (2)\n[q3]Microbot XD\nSi vincola alla raccolta\n[q2]Usa: Ti insegna a evocare questa mascotte.\n[q2]Clicca col pulsante destro per evocare e congedare questa mascotte.\nRichiede dal livello 1 al 80 ( 80)"}
MultiLanguageSpellData['it'][300271] = {name = "[q6]Differenziale Perfettamente a Tempo", additional_info = "1.5 s di lancio\nReagenti:\nCassa di Pezzi di Ricambio (2), Cella d'Energia (5), Oscillatore Galvanico (2)\n[q6]Differenziale Perfettamente a Tempo\nGrado 2\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Visione della Perfezione.\n50"}
MultiLanguageSpellData['it'][300272] = {name = "[q4]Zaino Antigravità", additional_info = "1.5 s di lancio\nReagenti:\nPezzi di Ricambio (200), Cella d'Energia (2)\n[q4]Zaino Antigravità\n(3)\nSi vincola alla raccolta\n[q2]Usa: Equipaggia uno Zaino Antigravità, attivabile facendo un doppio salto. Dura 20 min. Utilizzabile solo a Meccagon. (1 Min Recupero)"}
MultiLanguageSpellData['it'][300273] = {name = "Torretta Tascabile di Bullonaccio", additional_info = "1.5 s di lancio\nReagenti:\nPezzi di Ricambio (50), Cella d'Energia (3)\n(5)\nSi vincola alla raccolta\n[q2]Usa: Posiziona una Torretta delle Fiamme sul terreno che difende l'area per 2 minuti. Utilizzabile solo a Zandalar e Kul Tiras. (1 Min Recupero)"}
