MultiLanguageSpellData['it'][305992] = {name = "[q4]Pietra Alchemica Impareggiabile", additional_info = "3 s di lancio\nReagenti:\nZin'anthid (300), Alga d'Ancora (100), Espulsom (60)\n[q]Crea una Pietra Alchemica Impareggiabile.\nProfessione:\nAlchimia di Battle for Azeroth (165)\nScoperta:\nPietra Alchemica Risvegliata\n\n[q4]Pietra Alchemica Impareggiabile\nSi vincola alla raccolta\nUnico equipaggiabileMonile\n[q2]+ 16 Versatilità\n\n[q0]Incavo Prismatico\n\n[q2]Equipaggia: Fornire cure o infliggere danni fornisce una probabilità di aumentare Forza, Agilità o Intelletto di 42 per 15 s. Viene sempre scelto il tuo attributo più alto.\n[q2]Equipaggia: Aumenta l'effetto delle pozioni di mana e di cura del 40%. L'effetto non si accumula.\n50\nRichiedeAlchimia di Kul Tiras\n(175)\n[q]\"Può sostituire una Pietra Filosofale per le trasmutazioni.\""}
MultiLanguageSpellData['it'][305993] = {name = "[q4]Pietra Alchemica Risvegliata", additional_info = "3 s di lancio\nReagenti:\nZin'anthid (225), Alga d'Ancora (80), Espulsom (40)\n[q]Crea una Pietra Alchemica Risvegliata.\nProfessione:\nAlchimia di Battle for Azeroth (165)\nScoperta:\nPietra Alchemica Indomabile\n\n[q4]Pietra Alchemica Risvegliata\nSi vincola alla raccolta\nUnico equipaggiabileMonile\n[q2]+ 14 Versatilità\n\n[q0]Incavo Prismatico\n\n[q2]Equipaggia: Fornire cure o infliggere danni fornisce una probabilità di aumentare Forza, Agilità o Intelletto di 36 per 15 s. Viene sempre scelto il tuo attributo più alto.\n[q2]Equipaggia: Aumenta l'effetto delle pozioni di mana e di cura del 40%. L'effetto non si accumula.\n50\nRichiedeAlchimia di Kul Tiras\n(170)\n[q]\"Può sostituire una Pietra Filosofale per le trasmutazioni.\""}
MultiLanguageSpellData['it'][305994] = {name = "[q4]Pietra Alchemica Indomabile", additional_info = "3 s di lancio\nReagenti:\nZin'anthid (175), Alga d'Ancora (60), Espulsom (30)\n[q]Crea una Pietra Alchemica Indomabile.\nBottino:\nCultisti di N'zoth\n\n[q4]Pietra Alchemica Indomabile\nSi vincola alla raccolta\nUnico equipaggiabile: Pietra Alchemica (1)Monile\n[q2]+ 12 Versatilità\n\n[q0]Incavo Prismatico\n\n[q2]Equipaggia: Fornire cure o infliggere danni fornisce una probabilità di aumentare Forza, Agilità o Intelletto di 31 per 15 s. Viene sempre scelto il tuo attributo più alto.\n[q2]Equipaggia: Aumenta l'effetto delle pozioni di mana e di cura del 40%. L'effetto non si accumula.\nRichiedeAlchimia di Kul Tiras\n(165)\n[q]\"Può sostituire una Pietra Filosofale per le trasmutazioni.\""}
