MultiLanguageSpellData['it'][307381] = {name = "Pozione degli Esorcismi Potenziati", additional_info = "2 s di lancio\nReagenti:\nFiala dell'Avvistatore Runico , Vedovia (3), Bulbosso (3)\nProfessione:\nAlchimia di Shadowlands (135)\nIstruttore:\nMaestro degli Elisir Au'pyr\nZona:\nOribos\nCosto:\n8\n\n[q2]Usa: Gli incantesimi e le abilità d'attacco hanno una probabilità di far eruttare l'Animum del bersaglio, infliggendo fino a 3740 danni da ombra a tutti i nemici entro 10 m dal bersaglio.\n\n Se si consuma la pozione mentre l'arma è potenziata dall'Olio di Nucleombra, i danni aggiuntivi e la portata aumentano del 20%. Dura 25 s. (5 Min Recupero)\n51"}
MultiLanguageSpellData['it'][307382] = {name = "Pozione del Fuoco Fantasma", additional_info = "2 s di lancio\nReagenti:\nFiala dell'Avvistatore Runico , Bulbosso (3), Fior di Gloria (3)\nProfessione:\nAlchimia di Shadowlands (125)\nIstruttore:\nMaestro degli Elisir Au'pyr\nZona:\nOribos\nCosto:\n7\n\n[q2]Usa: Gli attacchi e gli incantesimi hanno una probabilità di scagliare un dardo infuocato contro il bersaglio, infliggendo 6270 danni da ombrofuoco.\n\n Se si consuma la pozione mentre l'arma è potenziata dall'Olio di Nucleombra, i danni aggiuntivi aumentano del 10%. Dura 25 s. (5 Min Recupero)\n51"}
MultiLanguageSpellData['it'][307383] = {name = "Pozione del Risveglio Divino", additional_info = "2 s di lancio\nReagenti:\nFiala dell'Avvistatore Runico , Fior di Gloria (3), Torcia della Veglia (3)\nProfessione:\nAlchimia di Shadowlands (125)\nIstruttore:\nMaestro degli Elisir Au'pyr\nZona:\nOribos\nCosto:\n7\n\n[q2]Usa: Gli incantesimi di cura forniscono fino a 11765 cure aggiuntive, in base alla salute mancante del bersaglio.\n\n Se si consuma la pozione mentre l'arma è potenziata dall'Olio dell'Imbalsamatore, le cure aggiuntive aumentano del 10%. Dura 25 s. (5 Min Recupero)\n51"}
MultiLanguageSpellData['it'][307384] = {name = "Pozione della Fissazione Letale", additional_info = "2 s di lancio\nReagenti:\nFiala dell'Avvistatore Runico , Vedovia (3), Torcia della Veglia (3)\nProfessione:\nAlchimia di Shadowlands (135)\nIstruttore:\nMaestro degli Elisir Au'pyr\nZona:\nOribos\nCosto:\n8\n\n[q2]Usa: Gli incantesimi e le abilità d'attacco hanno una probabilità di affliggere il bersaglio con Fissazione Letale, infliggendo 172 danni da ombra in 8 s. Si accumula fino a 5 volte. Al raggiungimento di 5 accumuli, Fissazione Letale esplode, infliggendo 3946 danni da ombra al bersaglio.\n\n Se si consuma la pozione mentre l'arma è potenziata dall'Olio di Nucleombra, i danni aggiuntivi aumentano del 10%. Dura 25 s. (5 Min Recupero)\n51"}
