MultiLanguageSpellData['it'][310484] = {name = "Granata Spaccanoci", additional_info = "2 s di lancio\nReagenti:\nManciata di Viti di Laestrite (3), Abrasivo Lucidante Poroso (2), Minerale di Laestrite\nProfessione:\nIngegneria di Shadowlands (10)\nIstruttore:\nMacchinista Au'gur\nZona:\nOribos\nCosto:\n30\n\n(2)\n[q2]Usa: Infligge 13939 danni da natura a tutti i nemici in un raggio di 5 m. (5 Min Recupero)\n51"}
MultiLanguageSpellData['it'][310485] = {name = "Mina d'Ombra", additional_info = "2 s di lancio\nReagenti:\nManciata di Viti di Laestrite (5), Abrasivo Lucidante Poroso (3), Minerale di Laestrite (3)\nProfessione:\nIngegneria di Shadowlands (20)\nIstruttore:\nMacchinista Au'gur\nZona:\nOribos\nCosto:\n75\n\n(2)\n[q2]Usa: Piazza sul terreno una mina che esplode quando un nemico si avvicina, infliggendo 13939 danni da ombra a tutti i nemici in un raggio di 5 m e scagliandoli in aria. (5 Min Recupero)\nRichiedeIngegneria di Shadowlands\n(1)"}
MultiLanguageSpellData['it'][310486] = {name = "Lanciatore di Bolas a Bomba", additional_info = "2 s di lancio\nReagenti:\nGranata Spaccanoci (3), Ingranaggio Vermipotenziato , Abrasivo Lucidante Poroso (5), Corteccia del Crepuscolo , Filo della Penombra (10)\nProfessione:\nIngegneria di Shadowlands (30)\nIstruttore:\nMacchinista Au'gur\nZona:\nOribos\nCosto:\n1\n15\n\n(2)\n[q2]Usa: Lancia un set di bombe legate insieme, che si avvinghiano intorno al primo nemico colpito ed esplodono dopo 5 s, infliggendo 13939 danni da fuoco ai nemici vicini. (5 Min Recupero)\nRichiedeIngegneria di Shadowlands\n(1)"}
MultiLanguageSpellData['it'][310490] = {name = "Stivali Ridistributori dell'Impeto", additional_info = "2 s di lancio 3\nStrumenti:\nChiave ad Arco , Martello da Fabbro\nReagenti:\nMolla dalle Spire Mortali (10), Manciata di Viti di Laestrite (20), Minerale di Fedrio (10), Cuoio Desolato (15), Stoffa Ammantata (20)\nProfessione:\nIngegneria di Shadowlands (65)\nIstruttore:\nMacchinista Au'gur\nZona:\nOribos\nCosto:\n2\n75\n\nSi vincola all'uso\n[q2]Usa: Ridistribuisce una porzione significativa dei danni altrimenti subiti dalla successiva caduta sui nemici vicini. Dura 10 s.\n\n Non funziona nelle incursioni, nelle spedizioni e nei contenuti istanziati. (5 Min Recupero)\nRichiedeIngegneria di Shadowlands\n(1)\n[q]\"Permette di fare un atterraggio supereroico!\""}
MultiLanguageSpellData['it'][310492] = {name = "Cannone del Disturbatore Gravimetrico", additional_info = "2 s di lancio 3\nStrumenti:\nChiave ad Arco , Martello da Fabbro\nReagenti:\nIngranaggio Vermipotenziato (3), Molla dalle Spire Mortali (3), Manciata di Viti di Laestrite (20), Abrasivo Lucidante Poroso (20), Minerale di Solenio (10), Scheggia Sacra (5)\nProfessione:\nIngegneria di Shadowlands (60)\nIstruttore:\nMacchinista Au'gur\nZona:\nOribos\nCosto:\n2\n50\n\nSi vincola all'uso\n[q2]Usa: Destabilizza la gravità intorno a una posizione bersaglio, intralciando i movimenti dei nemici vicini per 10 s e lanciandoli in direzioni casuali o scagliandoli in aria.\n\n A meno di malfunzionamenti.\nRichiedeIngegneria di Shadowlands\n(1)\n[q]\"A volte viene chiamato Generatore di Buchi Neri, ma non è preciso. È più un pezzo di artiglieria.\""}
MultiLanguageSpellData['it'][310493] = {name = "Trappola 4N1M4", additional_info = "2 s di lancio 3\nStrumenti:\nChiave ad Arco , Martello da Fabbro\nReagenti:\nIngranaggio Vermipotenziato (3), Molla dalle Spire Mortali (5), Manciata di Viti di Laestrite (10), Minerale di Fedrio (10), Polvere d'Anima (5)\nProfessione:\nIngegneria di Shadowlands (50)\nIstruttore:\nMacchinista Au'gur\nZona:\nOribos\nCosto:\n2\n\nSi vincola all'uso\n[q2]Usa: Piazza sul terreno un dispositivo di contenimento che, una volta armato, si attiva quando un nemico lo calpesta, esiliandolo per 1 min.\n\n A meno di malfunzionamenti.\n\n Effetto ridotto contro altri personaggi in PvP. (3 Min Recupero)\nRichiedeIngegneria di Shadowlands\n(1)\n[q]\"Con chi comunicherà?!?\""}
MultiLanguageSpellData['it'][310495] = {name = "Sfasatore Dimensionale", additional_info = "2 s di lancio\nRichiede Cinture\nStrumenti:\nChiave ad Arco\nReagenti:\nIngranaggio Vermipotenziato , Manciata di Viti di Laestrite (10), Minerale di Peccavyr (3), Ombril , Scheggia Immortale\n[q]Applica in modo permanente a un equipaggiamento per fianchi un dispositivo di distorsione tecnomagica della realtà, permettendo di diventare invisibili mentre si è fuori dal combattimento.\nProfessione:\nIngegneria di Shadowlands (45)\nIstruttore:\nMacchinista Au'gur\nZona:\nOribos\nCosto:\n1\n75"}
MultiLanguageSpellData['it'][310496] = {name = "Elettrosalto", additional_info = "2 s di lancio\nRichiede Cinture\nStrumenti:\nChiave ad Arco\nReagenti:\nIngranaggio Vermipotenziato , Manciata di Viti di Laestrite (10), Minerale di Solenio (3), Oriblasio , Scheggia Immortale\n[q]Applica in modo permanente a un equipaggiamento per fianchi un modificatore tecnomagico dello spazio-tempo, permettendo di teletrasportarsi istantaneamente a breve distanza in una direzione casuale.\nProfessione:\nIngegneria di Shadowlands (45)\nIstruttore:\nMacchinista Au'gur\nZona:\nOribos\nCosto:\n1\n75"}
MultiLanguageSpellData['it'][310497] = {name = "Restituitore di Danni", additional_info = "2 s di lancio\nRichiede Cinture\nStrumenti:\nChiave ad Arco\nReagenti:\nIngranaggio Vermipotenziato , Manciata di Viti di Laestrite (10), Minerale di Oxeina (3), Occhiostile , Scheggia Immortale\n[q]Applica in modo permanente a un equipaggiamento per fianchi un flusso magnetico tecnomagico che, all'attivazione, tiene sospese magicamente intorno a te tante piccole armi taglienti, infliggendo danni agli attaccanti.\nProfessione:\nIngegneria di Shadowlands (45)\nIstruttore:\nMacchinista Au'gur\nZona:\nOribos\nCosto:\n1\n75"}
MultiLanguageSpellData['it'][310499] = {name = "Miasma del Vuoto", additional_info = "Portata illimitata\nIstantaneo\n[q]Il Tentacolo di Drest'agath genera un miasma in un raggio di 12 m, infliggendo 4690 danni da ombra ogni 3 s a tutti i nemici nell'area d'effetto. I nemici all'esterno non possono puntare i bersagli dentro il Miasma del Vuoto ."}
MultiLanguageSpellData['it'][310501] = {name = "[q3]Visori Ectoplasmici Flessibili", additional_info = "2 s di lancio 3\nStrumenti:\nChiave ad Arco , Martello da Fabbro\nReagenti:\nIngranaggio Vermipotenziato (3), Manciata di Viti di Laestrite (5), Ombril (2), Stoffa Ammantata (10)\nReagenti Facoltativi:\nSpecifica una Statistica Secondaria (#17) , Specifica una Statistica Secondaria (#17) , Modifica livello oggetto - Maggiore (#16) , Aggiungi potenziamento del Progenitore (#79)\nProfessione:\nIngegneria di Shadowlands (85)\nIstruttore:\nMacchinista Au'gur\nZona:\nOribos\nCosto:\n5\n25\n\n[q3]Visori Ectoplasmici Flessibili\nSi vincola alla raccolta\nTesta Stoffa\n12 Armatura\n+18 Intelletto\n+27 Tempra\n[q2]+ 18 Attributo casuale 1\n[q2]+ 18 Attributo casuale 2\nIntegrità 85 / 85\n[q2]Equipaggia: Aumenta la competenza in Ingegneria di Shadowlands di 20.\n[q2]Usa: Permette di vedere molto lontano.\n60\nRichiedeIngegneria di Shadowlands\n(1)"}
