MultiLanguageSpellData['it'][312751] = {name = "Grinfia di Ha-Li", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"La nidiata di Ha-Li è a proprio agio nei cieli blu di Pandaria, dove caccia prede inconsapevoli.\"\nBottino:\nHa-Li\nZona:\nVallata dell'Eterna Primavera"}
