MultiLanguageSpellData['it'][312753] = {name = "Gargon Spezzasperanze", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Un tempo fedele cavalcatura del capo della Casata Rovotossico, si è rivoltata contro di lui e la sua scorta. Ora, i membri della Casata Rovotossico parlano di un Gargon oscuro che adesca i Venthyr che si inoltrano nei bui meandri del Distretto del Calice di Revendreth.\"\nCongrega:\nVenthyr\nZona:\nRevendreth"}
MultiLanguageSpellData['it'][312754] = {name = "Gargon da Battaglia Vrednic", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Vrednic, il fedele Gargon del Principe Renathal, è stato al suo fianco per millenni. Ornato con la sua armatura di Peccavyr, la mera presenza di Vrednic incute terrore a chiunque posi gli occhi su di lui, mentre accompagna il suo cavaliere in battaglia.\"\nCongrega:\nVenthyr\nZona:\nRevendreth"}
MultiLanguageSpellData['it'][312756] = {name = "PH Phalynx", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura."}
