MultiLanguageSpellData['it'][312759] = {name = "Cervo delle Rune della Luce dei Sogni", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"I Cervi delle Rune vengono donati a coloro che hanno giurato fedeltà alla Regina dell'Inverno e alla Corte della Notte.\"\nCongrega:\nSilfi della Notte\nZona:\nSelvarden"}
MultiLanguageSpellData['it'][312761] = {name = "Cervo delle Rune della Luce dei Sogni Incantato", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"I maestosi Cervi delle Rune sono capaci di risucchiare l'Animum ambientale di Selvarden con le loro antiche corna. L'Animum viene usato come nutrimento e potenzia la velocità e la magia dei Cervi delle Rune.\"\nCongrega:\nSilfi della Notte\nZona:\nSelvarden"}
MultiLanguageSpellData['it'][312762] = {name = "Cacciatore d'Anime dei Giurafauce", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"I Cacciatori d'Anime vengono utilizzati per seguire le anime che fuggono dal proprio oscuro destino in mezzo alle distese. Sono tra le poche creature che si trovano a proprio agio nella Fauce.\"\nBottino:\nSegugio d'Ombra Rimpinzato\nZona:\nLa Fauce"}
MultiLanguageSpellData['it'][312763] = {name = "Guscioduro Antronero", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"La chitina dei Guscioduro Antronero è tanto forte da resistere al fuoco di un mortaio o di un drago. Inoltre, se necessario, è in grado di consumare qualsiasi cosa cui manchi Animum.\"\nAvventure:\nTerretetre"}
MultiLanguageSpellData['it'][312764] = {name = "Replica della Conoscenza", additional_info = "Portata di 40 m\n[q]Replica della Conoscenza ora può copiare l'Essenza Maggiore del tuo bersaglio attuale, fino al Grado 2. L'aumento del tempo di recupero viene ridotto del 10%."}
