MultiLanguageSpellData['it'][314959] = {name = "Pinnavuota Impanato", additional_info = "2 s di lancio\nReagenti:\nPinna del Vuoto Aberrante (8), Carne di Dubbia Origine (3), Olio di Pesce Aromatico (3), Farina Selvatica (4)\n[q]Prepara un Pinnavuota Impanato.\nBottino:\nCultisti di N'zoth\n\n(5)\n[q2]Usa: Rigenera 50769 salute e 30769 mana in 20 s. Devi sederti per mangiare. Se mangi per almeno 10 s diventi Ben Nutrito.\n\n Essere Ben Nutriti aumenta la velocità di movimento del 20% nelle Visioni di N'zoth."}
MultiLanguageSpellData['it'][314960] = {name = "K'bab", additional_info = "2 s di lancio\nReagenti:\nCarne di Dubbia Origine (8), Masticatore Deforme (5), Pinna del Vuoto Aberrante (3), Olio di Pesce Aromatico (3)\n[q]Prepara del K'bab.\nBottino:\nCultisti di N'zoth\n\n(5)\n[q2]Usa: Rigenera 50769 salute e 30769 mana in 20 s. Devi sederti per mangiare.\n\n Se mangi per almeno 10 s, rigeneri istantaneamente 100 Sanità Mentale. (3 Min Recupero)"}
MultiLanguageSpellData['it'][314961] = {name = "Delizia Dubbia", additional_info = "2 s di lancio\nReagenti:\nCarne di Dubbia Origine (8), Olio di Pesce Aromatico (3), Farina Selvatica (3), Patata Novella (4)\n[q]Prepara una Delizia Dubbia.\nBottino:\nCultisti di N'zoth\n\n(5)\n[q2]Usa: Rigenera 50769 salute e 30769 mana in 20 s. Devi sederti per mangiare. Se mangi per almeno 10 s diventi Ben Nutrito.\n\n Essere Ben Nutriti riduce la durata degli effetti di controllo delle creature subiti del 20% nelle Visioni di N'zoth."}
MultiLanguageSpellData['it'][314962] = {name = "Gulasch Spettrale", additional_info = "2 s di lancio\nReagenti:\nCarne di Dubbia Origine (8), Pinna del Vuoto Aberrante (5), Masticatore Deforme (3), Olio di Pesce Aromatico (3)\n[q]Prepara del Gulasch Spettrale.\nBottino:\nCultisti di N'zoth\n\n(5)\n[q2]Usa: Rigenera 50769 salute e 30769 mana in 20 s. Devi sederti per mangiare. Se mangi per almeno 10 s diventi Ben Nutrito.\n\n Essere Ben Nutriti rigenera il 2% della salute massima ogni secondo nelle Visioni di N'zoth."}
MultiLanguageSpellData['it'][314963] = {name = "Masticatore alla Griglia", additional_info = "2 s di lancio\nReagenti:\nMasticatore Deforme (8), Carne di Dubbia Origine (3), Olio di Pesce Aromatico (3), Fusaka (4)\n[q]Prepara del Masticatore alla Griglia.\nBottino:\nCultisti di N'zoth\n\n(5)\n[q2]Usa: Rigenera 50769 salute e 30769 mana in 20 s. Devi sederti per mangiare. Se mangi per almeno 10 s diventi Ben Nutrito.\n\n Essere Ben Nutriti fornisce la forma di uno K'thir, riducendo la distanza a cui i nemici ti attaccano nelle Visioni di N'zoth per 10 min."}
