MultiLanguageSpellData['it'][320863] = {name = "Tocco della Morte", additional_info = "Istantaneo\n[q]Sfrutta il punto più debole del bersaglio nemico, infliggendo istantaneamente danni pari al 100% della tua salute massima [ Tocco della Morte Migliorato : al bersaglio, se ha meno salute di te / al bersaglio.\n\n Utilizzabile solo su creature che hanno meno salute di te.][ Infligge danni pari al 35% della tua salute massima a personaggi e creature più forti che hanno meno del 15% della salute massima ][ Mastro Birraio (Level 52) : Riduce i danni trascurati da Noncuranza del 200% dei danni inflitti ][ Impeto (Level 52) : Fa comparire 3 Sfere del Chi, che forniscono 1 chi quando le si attraversa ][ Tocco della Morte : Aumenta i danni fisici inflitti del 15% per 10 s ]"}
MultiLanguageSpellData['it'][320866] = {name = "Taglio Superiore", additional_info = "{100 energia} {Portata di 20 m}\n1 s di lancio\n[q]L'arma dell'incantatore colpisce fino a 2 bersagli frontali. Se viene colpito un solo bersaglio, questi resta affetto da Ferita Profonda."}
MultiLanguageSpellData['it'][320868] = {name = "[q3]Dizionario Orripilante", additional_info = "[q0][Anima Power]Istantaneo\n[q]Ogni diverso incantesimo Parola lanciato aumenta l'Intelletto del 10% per 5 min."}
MultiLanguageSpellData['it'][320869] = {name = "Brandelli Tinti di Luce", additional_info = "[q0][Anima Power]Istantaneo\n[q]Riduce il costo in mana di Cura Rapida del 30%."}
MultiLanguageSpellData['it'][320870] = {name = "Concentrazione Lampeggiante", additional_info = "[q0][Anima Power]Istantaneo\n[q][ Sacro : Cura Rapida /\n\nDisciplina, Ombra\nCura d'Ombra ] ripete il proprio effetto dopo 4 s, rigenerando salute pari al 50% dell'ammontare originale."}
MultiLanguageSpellData['it'][320871] = {name = "Zelo del Vandalo", additional_info = "[q0][Anima Power]Istantaneo\n[q]Distruggere un oggetto all'interno di Torgast potenzia il successivo lancio di [ Sacro : Fuoco Sacro /\n\nDisciplina, Ombra\nDetonazione Mentale ] del 3%. Si accumula fino a 40 volte."}
MultiLanguageSpellData['it'][320872] = {name = "[q3]Lampeggio", additional_info = "[q0][Anima Power]Istantaneo\n[q]Ogni 30 s durante i quali non si sta lanciando Cura Rapida, le cure fornite dalla successiva Cura Rapida sono aumentate del 100%. Si accumula fino a 6 volte."}
MultiLanguageSpellData['it'][320873] = {name = "Lanterna Rovente", additional_info = "[q0][Anima Power]Istantaneo\n[q]I lanci di Cura Rapida applicano Luminosità Rovente sui bersagli, così che riflettano il 50% dei danni subiti sugli attaccanti come danni da sacro per 20 s."}
MultiLanguageSpellData['it'][320874] = {name = "Benedizione del Sacerdote Caduto", additional_info = "[q0][Anima Power]Istantaneo\n[q]Disciplina\n Lanciare Detonazione Mentale aumenta i danni inflitti o le cure fornite dal successivo lancio di Contrizione del 30%. L'effetto si accumula, ma la durata non si rinnova.\n\nOmbra\n Lanciare Detonazione Mentale aumenta i danni inflitti o le cure fornite dal successivo lancio di Piaga Divoratrice del 30%. L'effetto si accumula, ma la durata non si rinnova.\n\nSacro\n Lanciare Fuoco Sacro aumenta i danni inflitti o le cure fornite dal successivo lancio di Parola Sacra: Castigo del 60%. L'effetto si accumula, ma la durata non si rinnova.\n(100ms di recupero)"}
MultiLanguageSpellData['it'][320875] = {name = "Melodia Logorante", additional_info = "[q0][Anima Power]Istantaneo\n[q]Aumenta la durata dei danni periodici inflitti da Fuoco Sacro di 4 s."}
MultiLanguageSpellData['it'][320876] = {name = "Fiasca di Sacrofuoco", additional_info = "[q0][Anima Power]Istantaneo\n[q]Fuoco Sacro ha una probabilità del 50% di non attivare il tempo di recupero."}
MultiLanguageSpellData['it'][320877] = {name = "Marchio della Protezione Virtuosa", additional_info = "[q0][Anima Power]Istantaneo\n[q]Riduce i danni subiti del 35% se c'è un nemico entro 10 m sotto un tuo effetto di Fuoco Sacro."}
MultiLanguageSpellData['it'][320878] = {name = "Pietra Infernale Sacra", additional_info = "[q0][Anima Power]Istantaneo\n[q]Quando termina, Fuoco Sacro salta su un bersaglio vicino aggiuntivo."}
MultiLanguageSpellData['it'][320879] = {name = "Mangiatore di Idee", additional_info = "[q0][Anima Power]Istantaneo\n[q]I colpi critici di Detonazione Mentale generano [ Ombra : 20 pazzia /\n\nDisciplina, Sacro\n1000 mana ]"}
MultiLanguageSpellData['it'][320880] = {name = "Ruota del Dolore", additional_info = "[q0][Anima Power]Istantaneo\n[q]Aumenta la durata di [ Epurazione dal Male / Parola d'Ombra: Dolore] di 3 s e aumenta i danni che infligge del 25%."}
MultiLanguageSpellData['it'][320881] = {name = "[q2]Fluorite del Dolore", additional_info = "[q0][Anima Power]Istantaneo\n[q]Quando l'effetto di Parola d'Ombra: Dolore termina su un bersaglio, tutti i membri del gruppo entro 20 m dal bersaglio rigenerano il 10% della propria salute massima."}
MultiLanguageSpellData['it'][320882] = {name = "[q3]Pensieri Incandescenti", additional_info = "[q0][Anima Power]Istantaneo\n[q]I danni iniziali inflitti da Parola d'Ombra: Dolore sono sempre critici."}
MultiLanguageSpellData['it'][320883] = {name = "[q2]Sacca con Cadavere di Ratto", additional_info = "[q0][Anima Power]Istantaneo\n[q]Uccidere un Rattofauce fornisce 1 carica aggiuntiva di Parola d'Ombra: Morte.\n\n La borsa può contenere fino a 28 Rattifauce morti."}
MultiLanguageSpellData['it'][320884] = {name = "[q3]Impulsor", additional_info = "[q0][Anima Power]Istantaneo\n[q]Sacro\n Lanciare Detonazione Mentale frastorna il bersaglio, riducendone la velocità di movimento e la probabilità d'impatto del 20% per 1 min.\n\n Eventuali successivi lanci di Fuoco Sacro o Detonazione Mentale dissolvono l'effetto.\n\nDisciplina, Ombra\n Lanciare Detonazione Mentale frastorna il bersaglio, riducendone la velocità di movimento e la probabilità d'impatto del 20% per 1 min.\n\n Eventuali successivi lanci di Fuoco Sacro o Detonazione Mentale dissolvono l'effetto."}
MultiLanguageSpellData['it'][320885] = {name = "[q3]Impulsor Modificato", additional_info = "[q0][Anima Power]Istantaneo\n[q]Lanciare [ Sacro (Level 12) : Fuoco Sacro /\n\nDisciplina, Ombra\nDetonazione Mentale ] non dissolve l'effetto Abbagliato."}
MultiLanguageSpellData['it'][320886] = {name = "[q3]Catastecca", additional_info = "[q0][Anima Power]Istantaneo\n[q]Il 20% di tutti i danni subiti vengono accumulati nella Catastecca. I danni iniziali inflitti dalla successiva Parola d'Ombra: Dolore infliggono al bersaglio anche questi danni accumulati."}
MultiLanguageSpellData['it'][320887] = {name = "[q4]Salmo Alleviante", additional_info = "[q0][Anima Power]Istantaneo\n[q]Parola d'Ombra: Morte consuma gli effetti di una tua [ Epurazione dal Male / Parola d'Ombra: Dolore] sul bersaglio, infliggendo istantaneamente tutti i danni restanti."}
MultiLanguageSpellData['it'][320888] = {name = "Scoppiamente", additional_info = "[q0][Anima Power]Istantaneo\n[q]Aumenta i danni inflitti da Detonazione Mentale del 500%, ma ne aumenta anche il tempo di recupero del 400%."}
