MultiLanguageSpellData['it'][320890] = {name = "Borsellino Psichico", additional_info = "[q0][Anima Power]Istantaneo\n[q]Lanciare Controllo Mentale su un nemico ne provoca lo svuotamento delle tasche, fornendo circa 15 Fantaplasma."}
MultiLanguageSpellData['it'][320891] = {name = "[q2]Ordine di Contagio", additional_info = "[q0][Anima Power]Istantaneo\n[q]Usare Controllo Mentale su un Rattofauce attiva Contagio Rapido, facendo sì che tutti i Rattifauce entro 15 m diano vita a una cucciolata di 2-5 Rattifauce aggiuntivi."}
