MultiLanguageSpellData['it'][320894] = {name = "Presa dell'Animum", additional_info = "[q0][Anima Power]Istantaneo\n[q]Casting Thoughtsteal on a target has a chance to grant you a Maw Power.  This effect can only occur once per level.\n\n NYI - Grants 3% all stats.\n(Possibilità di Apparire:20%)"}
