MultiLanguageSpellData['it'][320913] = {name = "[q2]Calzini Scaldini", additional_info = "[q0][Anima Power]Istantaneo\n[q]Blocco di Ghiaccio rigenera salute pari al 60% della tua salute massima per la durata dell'effetto e non arriva fino ai piedi, quindi è possibile muoversi... anche se lentamente."}
MultiLanguageSpellData['it'][320914] = {name = "[q3]Clessidra del Cronomante", additional_info = "[q0][Anima Power]Istantaneo\n[q]Alterazione Temporale fornisce una Distorsione Temporale aggiuntiva a se stessi e alle proprie Immagini Speculari con un'efficacia del 100%. Non subisce gli effetti di Spiazzamento Temporale o altri effetti simili.\n(1s di recupero)"}
