MultiLanguageSpellData['it'][320916] = {name = "[q4]Protezione della Trinità", additional_info = "[q0][Anima Power]Istantaneo\n[q]Lanciare un qualsiasi incantesimo Barriera fornisce gli effetti di Barriera Fiammeggiante, Barriera di Ghiaccio e Barriera Prismatica.\n(15s di recupero)"}
MultiLanguageSpellData['it'][320917] = {name = "Tesseratto Imbottigliato", additional_info = "[q0][Anima Power]Istantaneo\n[q]Aumenta la durata massima di Alterazione Temporale di 5 s."}
