MultiLanguageSpellData['it'][320920] = {name = "[q4]Paradosso dello Spezzatempo", additional_info = "[q0][Anima Power]Istantaneo\n[q]Aumenta la durata di Distorsione Temporale del 300%. Al termine dell'effetto, i personaggi affetti restano congelati nel tempo per 8 s."}
MultiLanguageSpellData['it'][320921] = {name = "[q2]Fasce di Telarunica", additional_info = "[q0][Anima Power]Istantaneo\n[q]I danni inflitti da Detonazione Arcana, Palla di Fuoco e Dardo di Gelo aumentano del 500% quando lanciati mentre il personaggio è Invisibile."}
MultiLanguageSpellData['it'][320922] = {name = "[q3]Scarabocchi del Mago Pazzo", additional_info = "[q0][Anima Power]Istantaneo\n[q]All'inizio di ogni piano, si riceve un'intuizione, che consiglia di lanciare una serie di incantesimi in un determinato ordine.\n\n Lanciare gli incantesimi nell'ordine corretto aumenta l'Intelletto del 5%."}
MultiLanguageSpellData['it'][320923] = {name = "[q3]Rilevatore Pulsazione Arcanica", additional_info = "[q0][Anima Power]Istantaneo\n[q]Quando si muore, si lancia automaticamente Invisibilità, diventando invisibili al Carceriere e impedendo che la propria morte venga notata.\n\n L'effetto quindi si consuma."}
MultiLanguageSpellData['it'][320924] = {name = "Filo del Tessispazio", additional_info = "[q0][Anima Power]Istantaneo\n[q]Riduce il tempo di recupero di Traslazione di 3 s."}
MultiLanguageSpellData['it'][320925] = {name = "[q4]Lama Dimensionale", additional_info = "[q0][Anima Power]Istantaneo\n[q]Passare attraverso un nemico con Traslazione rinnova il tempo di recupero di Traslazione. Passare attraverso i Rattifauce con Traslazione li uccide istantaneamente."}
