MultiLanguageSpellData['it'][323913] = {name = "Carne Sussultante", additional_info = "[q]Quando si forniscono cure agli alleati o se ne ricevono, la probabilità di critico aumenta del 1% per 10 s, fino a un massimo del 5%.\n\n Se si è potenziati da Osso Intarsiato di Rune, la probabilità di critico aumenta del 1% aggiuntivo per accumulo.\n(1s di recupero)"}
MultiLanguageSpellData['it'][323914] = {name = "Fildilama", additional_info = "[q]Gli attacchi e gli incantesimi hanno una probabilità di scatenare delle spade rotanti tutt'intorno a sé, infliggendo 500 danni da sanguinamento in 5 s.\n\n Se si è potenziati da Osso Intarsiato di Rune, i danni inflitti raddoppiano."}
MultiLanguageSpellData['it'][323915] = {name = "Stabilità del Giudicato", additional_info = "[q]Dopo aver inflitto 10.000 danni, si ottiene Stabilità, che rende immuni al successivo effetto inabilitante subito. L'effetto si dissolve quando si esce dal combattimento."}
MultiLanguageSpellData['it'][323916] = {name = "Emissione Solforica", additional_info = "[q0][Soulbind Ability][q]Quando si raggiunge meno del 20% della salute massima, i nemici vicini restano impauriti per 3.5 s. Può attivarsi solo una volta ogni 60 s."}
MultiLanguageSpellData['it'][323917] = {name = "Lista Nera", additional_info = "[q]Infliggere 10.000 danni a un nemico lo inserisce nella lista nera.\n Sconfiggere un nemico della propria lista nera aumenta l'indice di critico di 100 per 30 s, fino a un massimo di 1.000."}
