MultiLanguageSpellData['it'][327089] = {name = "Ora di Mangiare", additional_info = "Portata illimitata\nIstantaneo\n[q]Denathrius marchia dei personaggi casuali, quindi li colpisce dopo 5 s, infliggendo 47405 danni fisici ai personaggi entro 4 m da ogni bersaglio e curandosi del 150% dei danni inflitti."}
MultiLanguageSpellData['it'][327090] = {name = "Ripristino Costrutto", additional_info = "3 s di lancio\nReagenti:\nCarne Malleabile\n[q]Fa ritornare sul campo di battaglia un costrutto morto o andato perso di recente."}
MultiLanguageSpellData['it'][327091] = {name = "Duplicato Abominevole", additional_info = "3 s di lancio\nReagenti:\nCarne Malleabile (5), Pezzi Superiori\n[q]Un segnale del corno evoca Emeni, che ti aiuta in combattimento per un breve tempo."}
MultiLanguageSpellData['it'][327092] = {name = "Carestia", additional_info = "Portata di 100 m\nIstantaneo\n[q]Riduce i danni inflitti del 5%."}
MultiLanguageSpellData['it'][327093] = {name = "Pestilenza", additional_info = "Portata di 100 m\nIstantaneo\n[q]Infligge (150% of Attack power) danni da ombra in 6 s e riduce la velocità di movimento del bersaglio del 15%."}
MultiLanguageSpellData['it'][327095] = {name = "Morte", additional_info = "Portata di 100 m\nIstantaneo\n[q]Riduce le cure fornite del 5%."}
MultiLanguageSpellData['it'][327096] = {name = "Guerra", additional_info = "Portata di 100 m\nIstantaneo\n[q]Aumenta i danni subiti del 4%."}
MultiLanguageSpellData['it'][327097] = {name = "Spiriti Affini", additional_info = "[q0][Covenant Ability]{2% della base mana} {Portata di 40 m}\n2.5 s di lancio\n[q][ Guardiano Ferino : Difensore\nProtegge il compagno vincolato, reindirizzando il 40% dei danni che subisce su di te, a meno che tu non abbia meno del 20% della salute massima. ][ Rigenerazione : Guaritore\nPermette di concentrarsi sul compagno vincolato, replicando su di lui il 30% di tutte le cure fornite. /\n\nEquilibrio, Aggressore Ferino\nAssaltatore\nEnergizza il compagno vincolato, aumentando i danni da arcano, le cure o gli effetti d'assorbimento da lui forniti del 20% dei danni da te inflitti. ]"}
