MultiLanguageSpellData['it'][329580] = {name = "Bottiglia di Maelstrom Turbinoso", additional_info = "[q0][Anima Power]Istantaneo\n[q][ Potenziamento : Aumenta gli effetti di Arma del Maelstrom del 25% / Rigenerazione : Infligge [(125% of Spell power) * 1] danni da natura ogni 1 s a tutti i nemici nell'area d'effetto di Pioggia Curativa /\n\nElementale\nAumenta i danni inflitti da Terremoto del 150% e i danni inflitti da Folgore della Terra del 100% ]"}
