MultiLanguageSpellData['it'][332243] = {name = "Cervo delle Rune Foglialosca", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"I Cervi delle Rune Foglialosca vengono allevati dalla Caccia Selvaggia per la loro ferocia e la loro bellezza. Non hanno alcuna paura a penetrare nella tana di qualsiasi predatore.\"\nCongrega:\nSilfi della Notte\nZona:\nSelvarden"}
MultiLanguageSpellData['it'][332244] = {name = "Cervo delle Rune del Risvegliatore", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Ai Cervi delle Rune piace sdraiarsi vicino ai Semebrado. I Risvegliatori credono che possano sentire i sogni dei dormienti. I Cervi delle Rune mostrano un'ampia varietà di emozioni durante questa veglia, riflettendo i sogni o gli incubi degli spiriti nei Semebrado.\"\nCongrega:\nSilfi della Notte\nZona:\nSelvarden"}
MultiLanguageSpellData['it'][332245] = {name = "Cervo delle Rune Invernale", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"I Cervi delle Rune Invernali sono benedetti dalla Regina dell'Inverno in persona. Le loro rune brillano quando i predatori sono nelle vicinanze, avvertendo l'intero branco.\"\nCongrega:\nSilfi della Notte\nZona:\nSelvarden"}
MultiLanguageSpellData['it'][332246] = {name = "Cervo delle Rune Foglialosca Incantato", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Un Cervo delle Rune Foglialosca è capace di squartare creature potenti come una Matriarca Gorm, per difendere il suo branco. La Caccia Selvaggia cavalca queste cavalcature negli angoli più pericolosi delle Terretetre, quando il suo dominio dev'essere difeso da coloro che minacciano la natura selvaggia.\"\nCongrega:\nSilfi della Notte\nZona:\nSelvarden"}
MultiLanguageSpellData['it'][332247] = {name = "Cervo delle Rune del Risvegliatore Incantato", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"I Cervi delle Rune del Risvegliatore proteggono con ferocia la loro foresta di Semebrado. Quando i boschi iniziarono a seccarsi, molti esemplari s'infuriarono.\"\nCongrega:\nSilfi della Notte\nZona:\nSelvarden"}
MultiLanguageSpellData['it'][332248] = {name = "Cervo delle Rune Invernale Incantato", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"I Cervi delle Rune Invernali sono la cavalcatura preferita dalla Regina dell'Inverno in persona, la quale concede tale creatura solo ai suoi prediletti.\"\nCongrega:\nSilfi della Notte\nZona:\nSelvarden"}
