MultiLanguageSpellData['it'][336038] = {name = "Alalacera Immaturo", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Gli Alalacera sono una forza necessaria nel ciclo vitale delle Terretetre, perché sono sia preda che predatore nel duro ambiente di Maldraxxus.\"\nZona:\nMaldraxxus"}
MultiLanguageSpellData['it'][336039] = {name = "Alalacera Raccapricciante", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Gli Alalacera di Maldraxxus sono preziosi perché sono in grado di volare senza problemi attraverso i cieli delle Terretetre, permettendo al proprio cavaliere di cogliere l'opportunità per colpire i nemici o aiutare gli alleati.\"\nEdificio della Congrega:\nCorte delle Braci\nCongrega:\nVenthyr\n\nEdificio della Congrega:\nVivaio della Regina\nCongrega:\nSilfi della Notte\n\nEdificio della Congrega:\nVia dell'Ascensione\nCongrega:\nKyrian\n\nEdificio della Congrega:\nFabbrica degli Abomini\nCongrega:\nNecrosignori"}
