MultiLanguageSpellData['it'][336041] = {name = "Grifalco d'Ossa Ricucite", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Solo gli esperti ricucitori di carne che hanno dimostrato maestria nella magia di Maldraxxus sono abbastanza potenti da costruire un Grifalco della Morte di queste dimensioni.\"\nProfessione:\nCuciture Abominevoli\nZona:\nMaldraxxus"}
MultiLanguageSpellData['it'][336042] = {name = "Grifalco della Morte Gigantesco", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"I Grifalchi della Morte sono mostruosità ricucite con visceri, ossa e organi non necessari a ricostruire soldati per la Casata dei Costrutti.\"\nBottino:\nErrore Violaceo\nZona:\nMaldraxxus"}
