MultiLanguageSpellData['it'][336045] = {name = "Grifalco della Piaga Predatore", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"La fame eterna di Gieger è leggendaria nella Casata dei Costrutti, e nessuna bestia è troppo grande o con troppe ossa per entrare nel suo grosso stomaco.\"\nBottino:\nGieger\nCongrega:\nNecrosignori\nZona:\nMaldraxxus"}
