MultiLanguageSpellData['it'][337038] = {name = "[q5]Artiglio di Endereth", additional_info = "Abilità dell'Incisione Runica\n[q2]Aumenta la velocità di canalizzazione di Risucchio di Vita del 100% e ne aumenta la velocità di rigenerazione della salute del 100%.\n[q]Incisione Runica su: Fianchi, Piedi\n[q]Fonte: Missione: La Gran Banca\n[q]Richiede: Stregone"}
