MultiLanguageSpellData['it'][337042] = {name = "Trasformazione Spina", additional_info = "{1 s di lancio} {1 s di recupero}\n[q]Si trasforma, assumendo l'aspetto di un orso."}
MultiLanguageSpellData['it'][337043] = {name = "Nebbia Sciamante", additional_info = "[q0][Covenant Ability]Istantaneo\n[q]Una nebbia pesante ti circonda per 8 s, aumentando la probabilità di schivata del 10 %.\n\n Infligge (20% of Attack power) danni da ombra ogni 1 s ai nemici entro 10 m. Ogni volta che infligge danni ti fornisce 3 potenza runica, fino a un massimo di (30 / 10 * 5 ). Infligge danni ridotti oltre i 5 bersagli."}
MultiLanguageSpellData['it'][337044] = {name = "Marchio Peccaminoso", additional_info = "[q0][Covenant Ability]Istantaneo\n[q]Marchia un nemico con il marchio dei Venthyr, riducendone la velocità d'attacco in mischia del 30%, la velocità di lancio d'incantesimi del 30% e infliggendo (338% of Attack power) danni da ombra in 8 s.\n\n Attivare Metamorfosi Demoniaca applica Marchio Peccaminoso a tutti i nemici vicini."}
MultiLanguageSpellData['it'][337045] = {name = "Frenesia Vorace", additional_info = "[q0][Covenant Ability]Istantaneo\n[q]Per 20 s, gli incantesimi da Druido aumentano i danni inflitti e le cure fornite del 2% e la celerità del 1%. Si accumula.\n\n Se si resta inattivi per 2 s, Frenesia consuma il 1% della salute massima per accumulo, stordendo per 1 s, e termina."}
MultiLanguageSpellData['it'][337046] = {name = "Tiro Scorticato", additional_info = "[q0][Covenant Ability]Istantaneo\n[q]Colpisce il nemico, infliggendo (50% of Attack power) danni da ombra e facendolo sanguinare, infliggendo (112.5% of Attack power) danni da ombra in 18 s. Ogni volta che Tiro Scorticato infligge danni, fornisce una probabilità del 15% di ottenere Marchio dello Scorticatore, che permette di lanciare il successivo Tiro Mortale senza alcun costo e su qualsiasi bersaglio, a prescindere dalla salute e infliggendo il 25% di danni aggiuntivi."}
MultiLanguageSpellData['it'][337047] = {name = "Soffio Necrotico", additional_info = "Portata di 300 m\n{3 s di lancio} {5 s di recupero}\n[q]Infligge 40 danni da ombra a tutti i nemici frontali, riducendone le cure ricevute del 50% per 6 s."}
MultiLanguageSpellData['it'][337048] = {name = "Specchi del Tormento", additional_info = "[q0][Covenant Ability]Istantaneo\n[q]Evoca 3 specchi per tormentare il nemico per 25 s. Quando il bersaglio attacca, lancia un incantesimo o usa un'abilità, uno specchio si consuma, infliggendo (60% of Spell power) danni da ombra e riducendo la velocità di movimento e di lancio d'incantesimi del bersaglio del 15%. L'effetto non può verificarsi più di una volta ogni 6 s.\n\n L'ultimo specchio infligge (151% of Spell power) danni da ombra al nemico, immobilizzandolo e silenziandolo per 4 s.\n\n Quando uno specchio viene consumato [ Arcano : attiva Lancio Istintivo ][ Fuoco : riduce il tempo di recupero di Detonazione di Fuoco di 6 s ][ Gelo : attiva Mente Fredda ]"}
MultiLanguageSpellData['it'][337049] = {name = "Detonazione Congelante", additional_info = "Portata di 200 m\n3 s di lancio\n[q]Infligge 5 danni da gelo istantaneamente ai nemici entro 8 m e 1 danni da gelo aggiuntivi ogni 2 s, riducendone la velocità di movimento del 50% per 8 s."}
MultiLanguageSpellData['it'][337050] = {name = "Santificazione Cinerea", additional_info = "[q0][Covenant Ability]Istantaneo\n[q]Santifica l'area bersaglio per 30 s. I nemici nell'area d'effetto subiscono fino a [(55% of Spell power) * 30 / 2] danni da ombra e gli alleati vengono curati di massimo [(36% of Spell power) * 30 / 2] salute, quantità ridotte se ci sono più di 5 bersagli.\n\n All'interno dell'area d'effetto, è possibile lanciare Martello dell'Ira su qualsiasi bersaglio, infliggendo il 100% di danni aggiuntivi."}
MultiLanguageSpellData['it'][337051] = {name = "Giochi Mentali", additional_info = "[q0][Covenant Ability]Istantaneo\n[q]Assale la mente del nemico, infliggendo [(300% of Spell power) * 100 / 100] danni da ombra e invertendo brevemente la sua percezione della realtà.\n\n [ Ombra : Per 5 s, i successivi [(Spell power * 450 / 100) * (1 + Versatility) * 100 / 100] danni inflitti curano il bersaglio e le successive [(Spell power * 450 / 100) * (1 + Versatility) * 100 / 100] cure fornite danneggiano il bersaglio.\n\nI danni e le cure invertiti generano fino a 20 pazzia. /\n\nDisciplina, Sacro\nPer 5 s, i successivi [(Spell power * 450 / 100) * (1 + Versatility) * 100 / 100] danni inflitti curano il bersaglio e le successive [(Spell power * 450 / 100) * (1 + Versatility) * 100 / 100] cure fornite danneggiano il bersaglio.\n\nI danni e le cure invertiti ripristinano fino al 4% del mana massimo. ]"}
MultiLanguageSpellData['it'][337052] = {name = "Flagellazione", additional_info = "[q0][Covenant Ability]Istantaneo\n[q]Flagella il bersaglio, infliggendo (50% of Attack power) danni da ombra e facendo sì che ogni punto combo consumato entro 12 s infligga (10% of Attack power) danni aggiuntivi. Infliggere danni con Flagellazione aumenta la celerità del 1%. L'effetto bonus persiste per 12 s dopo la fine del tormento."}
MultiLanguageSpellData['it'][337053] = {name = "Detonazione Congelante", additional_info = "Portata di 200 m\nIstantaneo\n[q]Infligge 5 danni da gelo istantaneamente ai nemici entro 8 m e 1 danni da gelo aggiuntivi ogni 2 s, riducendone la velocità di movimento del 50% per 8 s."}
MultiLanguageSpellData['it'][337054] = {name = "Raccolto a Catena", additional_info = "[q0][Covenant Ability]Istantaneo\n[q]Invia un'ondata di Animum contro il bersaglio, saltando poi su bersagli vicini aggiuntivi. Infligge (205% of Spell power) danni da ombra a un massimo di 5 nemici e rigenera (315% of Spell power) salute a un massimo di 5 alleati.\n\n Per ogni bersaglio colpito da un effetto critico, il tempo di recupero di Raccolto a Catena si riduce di 5 s.[ Elementale : Genera 3 maelstrom per ogni bersaglio ferito o curato ]"}
MultiLanguageSpellData['it'][337055] = {name = "Catastrofe Imminente", additional_info = "[q0][Covenant Ability]Istantaneo\n[q]Richiama una nube di Animum caotico che si sposta sul bersaglio nemico, infliggendo (25.3% of Spell power) danni da ombra ai nemici sulla traiettoria. Quando l'Animum raggiunge il bersaglio, esplode, affliggendo tutti i nemici vicini con Maledizione della Debolezza o Maledizione delle Lingue e infliggendo (138% of Spell power) danni da ombra in 12 s."}
MultiLanguageSpellData['it'][337056] = {name = "Condanna", additional_info = "[q0][Covenant Ability]Istantaneo\n[q]Condanna sostituisce Esecuzione. Condanna infligge danni da ombra, può essere lanciata su nemici al di sopra del 80% o al di sotto del 20% della salute massima e indebolisce il bersaglio riducendone in parte i danni a te inflitti."}
MultiLanguageSpellData['it'][337057] = {name = "[q5]Reliquia della Sinergia Demoniaca", additional_info = "Abilità dell'Incisione Runica\nCirca 3 apparenze ogni minuto\n[q2]I danni inflitti da te e dal tuo servitore principale hanno una probabilità di aumentare i danni inflitti dall'altro, ossia rispettivamente dal servitore o da te, del [ Demonologia : 15% /\n\nAfflizione, Distruzione\n10% ] per 15 s.\n[q]Incisione Runica su: Testa, Spalle, Schiena\n[q]Fonte: Bottino Incursione: Generali della Legione di Pietra\n[q]Richiede: Stregone"}
MultiLanguageSpellData['it'][337058] = {name = "[q2]Ira degli Ascesi", additional_info = "[q0][Soulbind Conduit]Condotto della Potenza[q]Livello oggetto: 145\nRichiede Kyrian\n[q]Scintilla Radiante aumenta i danni inflitti dai tuoi incantesimi a quel bersaglio del 5.0% aggiuntivo."}
